    pin=snapshot();priorpath=BASE/pin['prior_own_ledger_path'];assert sha(priorpath.read_bytes())==pin['prior_own_ledger_sha256'];prior=json.loads(priorpath.read_text());reference=(BASE/pin['reference_path']).read_bytes();assert sha(reference)==pin['reference_original_sha256'];peer=json.loads(reference);numeric={(r['source_id'],r['page'],r['source_column'],r['candidate']):r for r in json.loads((OUT/'replay-60views-manual-repairs.json').read_text())['readings']};headers={(r['source_id'],r['page'],r['source_column']):r for r in json.loads((OUT/'replay-60views-header-repairs.json').read_text())['readings']};county={r['county'].lower().replace(' ','-'):r for r in csv.DictReader((BASE/'data/county-baselines.csv').open())};sources=list(prior['sources']);differences=[];boxrepairs=[];wraps=list(prior['explicit_wrap_representation_aliases']);checks=[]
