    save(OUT/'native-2024-senate-reviewed-60views.json',dict(qualification='60 bounded historical original source views, two named Senate fields only. Independent original extraction/readings preserve one frozen peer literal spelling difference and six target-to-reading box repairs explicitly; no normalized join, vote fitting or current2026 geometry approval.',prior_own_ledger_path=pin['prior_own_ledger_path'],prior_own_ledger_sha256=pin['prior_own_ledger_sha256'],checkpoint_reference_path=pin['reference_path'],checkpoint_reference_sha256=pin['reference_original_sha256'],explicit_wrap_representation_aliases=wraps,source_literal_peer_disagreements=differences,accepted_reading_box_repairs=boxrepairs,parsed_label_code_scope='Prior40rules retained; Chickasaw trailing3digits andHumphreys trailing4digits parsed from own original literal header, preserving leading zeros. Marshall/other beat prefixes stay literal, not asserted uniqueIDs. No cross-year/currentID equivalence.',sources=sources))
    writecsv(OUT/'native-2024-senate-reviewed-60views.csv',rows);save(OUT/'native-2024-senate-reviewed-controls-60views.json',dict(source_views=60,pages=sum(len(s['pages']) for s in sources),native_constituents=1373,native_candidate_positions=2746,TOTAL_candidate_positions=120,unused_null_candidate_positions=610,total_candidate_positions=len(rows),new20source_controls=checks,all60_parent_candidate_controls_exact=True,source_literal_peer_disagreements=differences,accepted_reading_box_repairs=boxrepairs,statewide_native_complete=False,presidential_native_complete=False));print('60views/1373native/3476candidatepositions;',len(differences),'literal source disagreement;',len(boxrepairs),'accepted source reading boxes separately repaired')
